sys_script_include.script:
var AchTransferHandler = Class.create();

AchTransferHandler.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAccounts: function() {
        var accounts = [];
        var isManager = gs.hasRole('x_274351_finance_0.manager') && !gs.hasRole('x_274351_finance_0.administrator');
        var gr = new GlideRecord('x_274351_finance_0_accounts');
        if (!isManager) {
            gr.addQuery('holder', gs.getUserID());
        }
        gr.addQuery('active', true);
        gr.orderBy('number');
        gr.query();
        while (gr.next()) {
            accounts.push({
                sys_id: gr.getUniqueValue(),
                number: gr.getValue('number'),
                account_type: gr.getValue('account_type'),
                balance: gr.getValue('balance')
            });
        }
        return JSON.stringify(accounts);
    },

    deposit: function() {
        var result = { success: false, message: '' };

        if (!gs.hasRole('x_274351_finance_0.manager')) {
            result.message = 'Only managers can perform deposits.';
            return JSON.stringify(result);
        }

        var accountSysId = this.getParameter('sysparm_account_sys_id');
        var amount = parseFloat(this.getParameter('sysparm_amount'));

        if (!accountSysId) {
            result.message = 'Missing required parameter: account_sys_id';
            return JSON.stringify(result);
        }
        if (isNaN(amount) || amount <= 0) {
            result.message = 'Amount must be a valid number greater than 0';
            return JSON.stringify(result);
        }

        var acctGr = new GlideRecord('x_274351_finance_0_accounts');
        if (!acctGr.get(accountSysId)) {
            result.message = 'Account not found';
            return JSON.stringify(result);
        }
        if (acctGr.getValue('active') != 'true' && acctGr.getValue('active') != '1') {
            result.message = 'Account is not active';
            return JSON.stringify(result);
        }

        var txnGr = new GlideRecord('x_274351_finance_0_txn');
        txnGr.initialize();
        txnGr.setValue('account', accountSysId);
        txnGr.setValue('type', 'deposit');
        txnGr.setValue('amount', amount);
        txnGr.setValue('status', 'completed');
        var txnSysId = txnGr.insert();

        if (!txnSysId) {
            result.message = 'Failed to create deposit transaction';
            return JSON.stringify(result);
        }

        result.success = true;
        result.message = 'Deposit of $' + amount.toFixed(2) + ' completed successfully';
        return JSON.stringify(result);
    },

    withdraw: function() {
        var result = { success: false, message: '' };

        if (!gs.hasRole('x_274351_finance_0.manager')) {
            result.message = 'Only managers can perform withdrawals.';
            return JSON.stringify(result);
        }

        var accountSysId = this.getParameter('sysparm_account_sys_id');
        var amount = parseFloat(this.getParameter('sysparm_amount'));

        if (!accountSysId) {
            result.message = 'Missing required parameter: account_sys_id';
            return JSON.stringify(result);
        }
        if (isNaN(amount) || amount <= 0) {
            result.message = 'Amount must be a valid number greater than 0';
            return JSON.stringify(result);
        }

        var acctGr = new GlideRecord('x_274351_finance_0_accounts');
        if (!acctGr.get(accountSysId)) {
            result.message = 'Account not found';
            return JSON.stringify(result);
        }
        if (acctGr.getValue('active') != 'true' && acctGr.getValue('active') != '1') {
            result.message = 'Account is not active';
            return JSON.stringify(result);
        }

        var currentBalance = parseFloat(acctGr.getValue('balance'));
        if (currentBalance < amount) {
            result.message = 'Insufficient funds. Current balance: $' + currentBalance.toFixed(2);
            return JSON.stringify(result);
        }

        var txnGr = new GlideRecord('x_274351_finance_0_txn');
        txnGr.initialize();
        txnGr.setValue('account', accountSysId);
        txnGr.setValue('type', 'withdrawal');
        txnGr.setValue('amount', amount);
        txnGr.setValue('status', 'completed');
        var txnSysId = txnGr.insert();

        if (!txnSysId) {
            result.message = 'Failed to create withdrawal transaction';
            return JSON.stringify(result);
        }

        result.success = true;
        result.message = 'Withdrawal of $' + amount.toFixed(2) + ' completed successfully';
        return JSON.stringify(result);
    },

    deactivateAccount: function() {
        var result = { success: false, message: '' };

        if (!gs.hasRole('x_274351_finance_0.administrator')) {
            result.message = 'Only administrators can deactivate accounts.';
            return JSON.stringify(result);
        }

        var accountSysId = this.getParameter('sysparm_account_sys_id');

        if (!accountSysId) {
            result.message = 'Missing required parameter: account_sys_id';
            return JSON.stringify(result);
        }

        var acctGr = new GlideRecord('x_274351_finance_0_accounts');
        if (!acctGr.get(accountSysId)) {
            result.message = 'Account not found';
            return JSON.stringify(result);
        }
        if (acctGr.getValue('active') != 'true' && acctGr.getValue('active') != '1') {
            result.message = 'Account is already inactive';
            return JSON.stringify(result);
        }

        acctGr.setValue('active', false);
        acctGr.update();

        result.success = true;
        result.message = 'Account has been deactivated successfully';
        return JSON.stringify(result);
    },

    reactivateAccount: function() {
        var result = { success: false, message: '' };

        if (!gs.hasRole('x_274351_finance_0.administrator')) {
            result.message = 'Only administrators can reactivate accounts.';
            return JSON.stringify(result);
        }

        var accountSysId = this.getParameter('sysparm_account_sys_id');

        if (!accountSysId) {
            result.message = 'Missing required parameter: account_sys_id';
            return JSON.stringify(result);
        }

        var acctGr = new GlideRecord('x_274351_finance_0_accounts');
        if (!acctGr.get(accountSysId)) {
            result.message = 'Account not found';
            return JSON.stringify(result);
        }
        if (acctGr.getValue('active') == 'true' || acctGr.getValue('active') == '1') {
            result.message = 'Account is already active';
            return JSON.stringify(result);
        }

        acctGr.setValue('active', true);
        acctGr.update();

        result.success = true;
        result.message = 'Account has been reactivated successfully';
        return JSON.stringify(result);
    },

    processTransfer: function() {
        var accountSysId = this.getParameter('sysparm_account_sys_id');
        var amount = this.getParameter('sysparm_amount');
        var description = this.getParameter('sysparm_description');
        var webhookKey = this.getParameter('sysparm_webhook_key');

        var result = {
            success: false,
            message: '',
            transaction: null
        };

        // Validate inputs
        if (!accountSysId || !amount || !webhookKey) {
            result.message = 'Missing required parameters: account_sys_id, amount, and webhook_key are required';
            return JSON.stringify(result);
        }

        // Verify the account exists
        var acctGr = new GlideRecord('x_274351_finance_0_accounts');
        if (!acctGr.get(accountSysId)) {
            result.message = 'Account not found with sys_id: ' + accountSysId;
            return JSON.stringify(result);
        }

        // Create the transaction record
        var txnGr = new GlideRecord('x_274351_finance_0_txn');
        txnGr.initialize();
        txnGr.setValue('account', accountSysId);
        txnGr.setValue('type', 'ach_transfer');
        txnGr.setValue('amount', amount);
        txnGr.setValue('status', 'completed');
        var txnSysId = txnGr.insert();

        if (!txnSysId) {
            result.message = 'Failed to create transaction record';
            return JSON.stringify(result);
        }

        // Send webhook notification
        try {
            var restMessage = new sn_ws.RESTMessageV2();
            restMessage.setEndpoint('https://webhook.site/' + webhookKey);
            restMessage.setHttpMethod('POST');
            restMessage.setRequestHeader('Content-Type', 'application/json');

            var payload = {
                transaction_id: txnSysId,
                account_number: acctGr.getValue('number'),
                account_holder: acctGr.getDisplayValue('holder'),
                type: 'ach_transfer',
                amount: amount,
                description: description || '',
                timestamp: new GlideDateTime().getDisplayValue()
            };

            restMessage.setRequestBody(JSON.stringify(payload));
            var response = restMessage.execute();
            var httpStatus = response.getStatusCode();

            result.success = true;
            result.message = 'ACH transfer processed successfully. Webhook status: ' + httpStatus;
            result.transaction = {
                sys_id: txnSysId,
                account_number: acctGr.getValue('number'),
                amount: amount,
                type: 'ach_transfer',
                status: 'completed',
                webhook_status: httpStatus
            };
        } catch (e) {
            // Transaction was created, but webhook failed
            result.success = true;
            result.message = 'Transaction created but webhook notification failed: ' + e.getMessage();
            result.transaction = {
                sys_id: txnSysId,
                account_number: acctGr.getValue('number'),
                amount: amount,
                type: 'ach_transfer',
                status: 'completed',
                webhook_status: 'failed'
            };
        }

        return JSON.stringify(result);
    },

    type: 'AchTransferHandler'
});
